"""The JSON risk report (REP-01)."""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from pathlib import Path

from risk.types import Drawdown, Report, TickerSummary


def write_report(
    summary: Sequence[TickerSummary], drawdowns: Sequence[Drawdown], out_path: str | Path
) -> Report:
    """Write `{"tickers": [...]}` to `out_path`, one row per ticker, sorted.

    Raises ValueError if summary and drawdowns cover different tickers.
    """
    by_ticker = {d.ticker: d for d in drawdowns}
    summary_tickers = {s.ticker for s in summary}
    if summary_tickers != set(by_ticker):
        raise ValueError(
            f"summary covers {sorted(summary_tickers)} but drawdowns cover {sorted(by_ticker)}"
        )
    rows = tuple(
        _row(s, by_ticker[s.ticker]) for s in sorted(summary, key=lambda s: s.ticker)
    )
    path = Path(out_path)
    path.write_text(json.dumps({"tickers": list(rows)}, indent=2) + "\n")
    return Report(path=str(path), rows=rows)


def _row(summary: TickerSummary, drawdown: Drawdown) -> Mapping[str, object]:
    return {
        "ticker": summary.ticker,
        "ann_return": summary.ann_return,
        "ann_vol": summary.ann_vol,
        "sharpe": summary.sharpe,
        "last_vol": summary.last_vol,
        "max_drawdown": drawdown.depth,
        "peak_date": drawdown.peak_date,
        "trough_date": drawdown.trough_date,
    }

